var houses;
var origin;
var street;

function setup() {
	createCanvas(windowWidth, windowHeight);
  pixelDensity(1);
  frameRate(30);
  // // noLoop() removed for animation

  origin = {x: width * 0.5, y: height * 0.5}
  street = {w: 4 * width, h: height * 0.15}

  houses = [];
  for (i = 0; i < 150; i++) {
    let y = random(height);
    const h = random(height*0.1, height*0.2)
    // if (y < origin.y && y + h > origin.y - street.h * 0.5) y = origin.y - street.h * 0.5 - h;
    // if (y >= origin.y && y < origin.y + street.h * 0.5) y = origin.y + street.h * 0.5;
    if (y < origin.y && y + h > origin.y - street.h) y = origin.y - street.h - h;
    if (y >= origin.y && y < origin.y + street.h) y = origin.y + street.h;
    let house = new House(random(street.w), y, random(width*0.1,width*0.2), h);
    if (!house.overlaps(houses)) {
      houses.push(house);
    }
  }
}


function draw() {
  background(32); // "beige"
	translate(width*0.5, height*0.5)
	rotate(-HALF_PI)
	translate(-width*0.5, -height*0.5)

  noFill()
  stroke("#0f478c"); // rgb(15,71,140)
  fill("beige");

  // houses.sort((a, b) => -dist(origin.x, origin.y, a.x + a.w * 0.5, a.y + a.h * 0.5) + dist(origin.x, origin.y, b.x + b.w * 0.5, b.y + b.h * 0.5));
  houses.sort((a, b) => b.distanceOrigin() - a.distanceOrigin());
  for (h of houses) {
    h.update()
    h.show()
  }

  push();
  rectMode(CENTER); translate(origin.x, origin.y)
	fill("gray")
  rect(0, 0, street.w, street.h)
  pop();
}


// line intercept math by Paul Bourke http://paulbourke.net/geometry/pointlineplane/
// Determine the intersection point of two line segments
// Return FALSE if the lines don't intersect
function intersect(x1, y1, x2, y2, x3, y3, x4, y4) {

  // Check if none of the lines are of length 0
	if ((x1 === x2 && y1 === y2) || (x3 === x4 && y3 === y4)) {
		return false
	}

	denominator = ((y4 - y3) * (x2 - x1) - (x4 - x3) * (y2 - y1))

  // Lines are parallel
	if (denominator === 0) {
		return false
	}

	let ua = ((x4 - x3) * (y1 - y3) - (y4 - y3) * (x1 - x3)) / denominator
	let ub = ((x2 - x1) * (y1 - y3) - (y2 - y1) * (x1 - x3)) / denominator

  // is the intersection along the segments
	if (ua < 0 || ua > 1 || ub < 0 || ub > 1) {
		return false
	}

  // Return a object with the x and y coordinates of the intersection
	let x = x1 + ua * (x2 - x1)
	var y = y1 + ua * (y2 - y1)

	return {x, y}
}

class House {
  constructor(x, y, w, h) {
    this.x = x;
    this.y = y;
    this.w = w;
    this.h = h;
		this.clr = random([color("darkred"), color("darkgreen"), color("darkblue"), color("rgb(1,40,60)")]);
  }

  update() {
    this.x -= 15;
    if (this.x + this.w < -street.w * 0.5) {
      this.x = street.w * 0.5;
    }
  }

  show() {
    push();
    /*
    line(origin.x, origin.y, this.x, this.y)
    line(origin.x, origin.y, this.x + this.w, this.y)
    line(origin.x, origin.y, this.x, this.y + this.h)
    line(origin.x, origin.y, this.x + this.w, this.y + this.h)
    */
    const [x, y, w, h, o] = [this.x, this.y, this.w, this.h, origin];
    strokeWeight(1);
		noStroke()
		fill(this.clr)
    if (y > o.y) {
      // upper
      triangle(x, y + h, x + w, y + h, o.x, o.y)
      this.showSides();
      triangle(x, y, x + w, y, o.x, o.y)
    } else {
      // down
      triangle(x, y, x + w, y, o.x, o.y)
      this.showSides();
      triangle(x, y + h, x + w, y + h, o.x, o.y)
    }
    strokeWeight(2);
		fill(this.clr)
    rect(this.x, this.y, this.w, this.h)
    pop();
  }

  showSides() {
    push()
    const [x, y, w, h, o] = [this.x, this.y, this.w, this.h, origin];

    if (x < o.x) {
      triangle(x, y, x, y + h, o.x, o.y)
      triangle(x + w, y, x + w, y + h, o.x, o.y)
    } else {
      triangle(x + w, y, x + w, y + h, o.x, o.y)
      triangle(x, y, x, y + h, o.x, o.y)
    }

    pop();
  }

  overlaps(houses) {
    for (h of houses) {
      const l1 = {x: this.x, y: this.y + this.h}
      const r1 = {x: this.x + this.w, y: this.y}
      const l2 = {x: h.x, y: h.y + h.h}
      const r2 = {x: h.x + h.w, y: h.y}
      // if (this.intersects(h)) return true;
      if ((l1.x <= r2.x && l2.x <= r1.x && r1.y <= l2.y && r2.y <= l1.y)) return true;
      if (this.x <= h.x + h.w &&
        h.x <= this.x + this.w &&
        this.y <= h.y + h.h &&
        h.y <= this.y + this.h) return true;
    }
    return false;
  }

  distanceOrigin() {
    const o = origin;
    const mi = {x: this.x, y: this.y + this.h}
    const ma = {x: this.x + this.w, y: this.y}
    var dx = Math.max(mi.x - o.x, 0, o.x - ma.x);
    var dy = Math.max(mi.y - o.y, 0, o.y - ma.y);
    return Math.sqrt(dx*dx + dy*dy);
  }
}
